  "3SU1102-6AA40-1AA0 — signálka Ø22, plast, zelená hladká čočka, s držákem a LED modulem 24 V AC/DC, šroubové svorky": "3SU1102-6AA40-1AA0 — 指示灯 Ø22，塑料，绿色光滑透镜，带支架和 LED 模块 24 V AC/DC，螺钉端子",
  "3SU1150-1HB20-1CH0 — hřibové tlačítko nouzového zastavení, kov, 40 mm, uvolnění pootočením, 1 NC, s držákem": "3SU1150-1HB20-1CH0 — 急停蘑菇头按钮，金属，40 mm，旋转释放，1 NC，带支架",
  "4 AO, napětí / proud (0–10 V, ±10 V, 0–20 mA, 4–20 mA)": "4 AO，电压 / 电流（0–10 V，±10 V，0–20 mA，4–20 mA）",
  "4. **Zařízení** — dolaď sestavu; Import existujícího projektu je vedlejší volba dole.": "4. **设备** — 调整设备配置；导入现有项目是下方的辅助选项。",
  "4. I/O bilance a moduly": "4. I/O 统计与模块",
