  "Analogy: moduly 5069-IF8 / 5069-OF4 dávají a berou Chxx.Data jako REAL. V konfiguraci modulu\n  nastav Low/High Engineering 0–100 (procenta rozsahu); bloky přepočítají 0–100 % na\n  scaleMin…scaleMax (rawMax = 100.0).": "模拟量：5069-IF8 / 5069-OF4 模块以 REAL 类型提供和接收 Chxx.Data。在模块配置中\n  将 Low/High Engineering 设为 0–100（量程百分比）；功能块将 0–100 % 换算为\n  scaleMin…scaleMax（rawMax = 100.0）。",
