  "Bez jakékoli závady program vyhlásí poruchu v čase {t} s ({model}). Hlídací čas kroku nebo timeout bloku (motor {motor} s, ventil {valve} s) je kratší než skutečná doba akce — prodluž čas kroku, nebo uprav model stroje.": "在没有任何异常的情况下，程序在 {t} s 时报出故障（{model}）。步监控时间或功能块超时（电机 {motor} s，阀 {valve} s）短于动作的实际时间 — 请延长步时间，或调整机器模型。",
  "Bez kontaktního bloku (dle ABB); balení min. 10 ks.": "不含触点块（按 ABB）；最少包装 10 件。",
  "Bez sekvence se vygenerují jen instance zařízení s TODO povely pro ruční režim.": "没有顺序控制时，仅生成带手动模式 TODO 命令的设备实例。",
  "Bez sekvence se vygenerují jen instance zařízení s ručními povely z HMI (manRun_* / manOpen_*).": "没有顺序控制时，仅生成带 HMI 手动命令 (manRun_* / manOpen_*) 的设备实例。",
  "Bez zásahu — hodnotu řídí program.": "无干预 — 数值由程序控制。",
  "Bezpečnost — co NIKDY neřešit jen programem": "安全 — 哪些功能绝不可仅靠程序实现",
  "Bezpečnostní funkce (nouzové zastavení, kryty, dvouruční ovládání) realizuje certifikovaná bezpečnostní technika dle posouzení rizik (ISO 13849 / IEC 62061) — nejsou předmětem tohoto programu. Signály v PLC slouží pouze k blokování technologie a diagnostice.": "安全功能（急停、防护罩、双手操作）由经认证的安全技术按风险评估 (ISO 13849 / IEC 62061) 实现 — 不属于本程序的范围。PLC 中的信号仅用于工艺联锁和诊断。",
