  "Bloky zařízení jsou Add-On Instructions (ST) ze stejných šablon jako u ostatních platforem:\n  TON → TONR (FBD_TIMER, PRE v ms se nastaví před voláním), WORD → DINT, RETURN → ELSE.\n  Instance se volají přes členy: instM1.enable := …; FB_Motor(instM1); M1_outRun := instM1.outRun;": "设备块是 Add-On Instructions (ST)，与其他平台使用相同的模板：\n  TON → TONR（FBD_TIMER，以 ms 为单位的 PRE 在调用前设置），WORD → DINT，RETURN → ELSE。\n  实例通过其成员调用：instM1.enable := …; FB_Motor(instM1); M1_outRun := instM1.outRun;",
