  "GVL_IO.st: PLC projekt → Add → Global Variable List, vlož obsah.\n  Adresy %IX/%QX můžeš nechat a nalinkovat v I/O mapování, nebo použít AT %I*.": "GVL_IO.st：PLC 项目 → Add → Global Variable List，粘贴内容。\n  %IX/%QX 地址可以保留并在 I/O 映射中链接，也可以使用 AT %I*。",
