  "Gen_IO.xml: import přes Openness. Pro V17–V20 přepiš v hlavičce Engineering version V21 na svou verzi; jazyk komentářů (Culture) musí být mezi jazyky projektu.": "Gen_IO.xml：通过 Openness 导入。V17–V20 请把文件头中的 Engineering version V21 改为您的版本；注释语言（Culture）必须属于项目语言。",
  "Gen_Library.scl a Gen_Main.scl: Program blocks → External source files →\n  Add new external file → pravý klik → Generate blocks from source (NEJDŘÍV knihovnu).": "Gen_Library.scl 和 Gen_Main.scl：Program blocks → External source files →\n  Add new external file → 右键单击 → Generate blocks from source（先导入库）。",
  "Gen_Library.st / MAIN.st: editor POU má dvě části — do HORNÍ (deklarace) vlož řádky od FUNCTION_BLOCK / PROGRAM po poslední END_VAR, do DOLNÍ (implementace) zbytek BEZ END_FUNCTION_BLOCK / END_PROGRAM. Každý blok jako nový POU (Function Block, ST).": "Gen_Library.st / MAIN.st：POU 编辑器分两部分 — 上半部分（声明）粘贴从 FUNCTION_BLOCK / PROGRAM 到最后一个 END_VAR 的行，下半部分（实现）粘贴其余内容，不含 END_FUNCTION_BLOCK / END_PROGRAM。每个块作为新的 POU（Function Block，ST）。",
  "Gen_Library.st: Function Block do knihovny projektu (jazyk ST).": "Gen_Library.st：将 Function Block 加入项目库（ST 语言）。",
  "Gen_Library.st: každý FUNCTION_BLOCK vlož jako nový POU (ST).": "Gen_Library.st：将每个 FUNCTION_BLOCK 作为新的 POU (ST) 插入。",
  "Gen_Library.st: každý blok jako Function Block (ST) do POUs → Function Blocks; vstup kvitace se jmenuje resetIn (Reset je instrukce Sysmac).": "Gen_Library.st：每个块作为 Function Block（ST）放入 POUs → Function Blocks；复位输入名为 resetIn（Reset 是 Sysmac 指令）。",
  "Gen_Main.scl – strojní blok (multi-instance). Import PO Gen_Library.scl.": "Gen_Main.scl – 机器功能块（多重实例）。在 Gen_Library.scl 之后导入。",
  "Gen_Tags.tsv: otevři v Excelu (UTF-8, oddělovač tabulátor), list přejmenuj na „PLC Tags“, ulož jako .xlsx a v tabulce tagů dej Import (sloupce Name / Data Type / Logical Address / Comment odpovídají formátu TIA).": "Gen_Tags.tsv：在 Excel 中打开（UTF-8，制表符分隔），将工作表重命名为“PLC Tags”，另存为 .xlsx，然后在变量表中选择导入（Name / Data Type / Logical Address / Comment 列与 TIA 格式一致）。",
  "Generované zdroje": "生成的源文件",
  "Generovat": "生成",
  "Generování": "生成",
  "GlobalLabels.csv: Navigation → Label → Global Label → import CSV\n  (sloupec Assign obsahuje návrh X/Y — ověř dle skutečných modulů; formát CSV\n  se liší podle verze GX Works3, srovnej s exportem ze své instalace).": "GlobalLabels.csv：Navigation → Label → Global Label → 导入 CSV\n  （Assign 列为建议的 X/Y 地址 — 请按实际模块核对；CSV 格式\n  因 GX Works3 版本而异，请与本机安装导出的文件对比）。",
  "Globální tagy vidí ST funkce jen přes seznam Used Globals (vlastnosti funkce) — přidej do něj všechny tagy z Tags.csv.": "ST 函数只能通过 Used Globals 列表（函数属性）访问全局变量 — 请把 Tags.csv 中的所有变量加入该列表。",
  "HMI je součástí CPU UniStream (5\"/7\"/10,4\") – samostatná položka se nepočítá": "HMI 集成在 UniStream CPU 中（5\"/7\"/10.4\"）– 不单独计算",
