  "HPT 24 V DC — membránová siréna 108 dB, 0,6 A, IP55, Ø132×330 mm, vývodka PG13.5": "HPT 24 V DC — 膜片式警报器 108 dB，0.6 A，IP55，Ø132×330 mm，电缆接头 PG13.5",
