  "Hensel s.r.o. v Roudnici n. L. (od 1992) prodává výrobky Hensel a sama vyrábí rozvaděče do 1000 V / 2000 A. Elektro Bečov (výrobní družstvo, Bečov n. T.) je samostatný výrobce svorek, ne výrobce skříní Hensel — viz terminal_block.": "Hensel s.r.o.（Roudnice n. L.，自 1992 年起）销售 Hensel 产品并自行制造 1000 V / 2000 A 以下配电柜。Elektro Bečov（生产合作社，Bečov n. T.）是独立的端子制造商，不是 Hensel 机柜制造商 — 见 terminal_block。",
