  "Komentář": "注释",
  "Kompaktní spouštěč": "紧凑型起动器",
  "Kompaktní: ADN-32-25-A-P-A, obj. č. 536272 (https://ftp.festo.com/public/PNEUMATIC/SOFTWARE_SERVICE/DataSheet/EN_GB/536272.pdf).": "紧凑型：ADN-32-25-A-P-A，订货号 536272（https://ftp.festo.com/public/PNEUMATIC/SOFTWARE_SERVICE/DataSheet/EN_GB/536272.pdf）。",
