  "Krok může čekat i na digitální vstup (snímač dílu, výsledek kontroly, tlačítko obsluhy): přechod je vždy stav vstupu a zadaný čas je hlídací.": "步也可以等待数字量输入（零件传感器、检测结果、操作按钮）：转换条件始终是输入状态，所填时间为监控时间。",
