  "Kvitace poruchy": "故障确认",
  "Kód 8086607 = rozhraní CPX-AP-I-PN-M12, ne celý terminál. VAEM-L1-S-8-PT má obj. č. 573384 (https://ftp.festo.com/public/PNEUMATIC/SOFTWARE_SERVICE/DataSheet/EN_GB/573384.pdf). Celý terminál se konfiguruje v konfigurátoru Festo.": "订货号 8086607 = 接口 CPX-AP-I-PN-M12，不是整个阀岛。VAEM-L1-S-8-PT 订货号 573384（https://ftp.festo.com/public/PNEUMATIC/SOFTWARE_SERVICE/DataSheet/EN_GB/573384.pdf）。整个阀岛在 Festo 配置器中配置。",
  "Kód Bürkert ze zahraničního distributora (popis: 2873, 1 mm, 14 bar, G1/8, FKM, 24 V DC). Světlost volit podle průtoku (0,8–6 mm, https://www.burkert.com/en/type/2873). Elektronika 8605 se objednává zvlášť. Type 2875 neověřen.": "Bürkert 订货号来自国外经销商（描述：2873，1 mm，14 bar，G1/8，FKM，24 V DC）。通径按流量选择（0.8–6 mm，https://www.burkert.com/en/type/2873）。电子模块 8605 需单独订购。Type 2875 未核实。",
  "Kód JZ-500 neověřen.": "JZ-500 订货号未核实。",
  "Kód OEZ:41655 uveden i na elektro-malinsky.cz.": "OEZ:41655 也见于 elektro-malinsky.cz。",
  "Kód je jen SI jednotka; ostrov se konfiguruje u SMC.": "订货号仅为 SI 单元；阀岛在 SMC 处配置。",
  "Kód je typové označení — převod a provedení doplnit při objednávce. Motor 80 LP/4 samostatně: https://shop.nord.com/IT-de/80-lp4-iec-b5-a200-230400v-bre-10nm-385.html": "订货号为型号标识 — 订购时补充传动比和型式。单独电机 80 LP/4：https://shop.nord.com/IT-de/80-lp4-iec-b5-a200-230400v-bre-10nm-385.html",
  "Kód je typové označení — převod, provedení hřídele, polohu a napětí doplní konfigurátor SEW. Příklad: R37 DRN80M4 s i = 36,72 → 48 min-1 (US provedení 230/460 V, https://www.mrosupply.com/speed-reducers/2977677_r37-drn80m4_sew-eurodrive/).": "订货号为型号标识 — 传动比、轴型式、安装位置和电压由 SEW 配置器补充。示例：R37 DRN80M4，i = 36.72 → 48 min-1（美国型号 230/460 V，https://www.mrosupply.com/speed-reducers/2977677_r37-drn80m4_sew-eurodrive/）。",
  "Kód se skládá konfigurátorem.": "订货号由配置器生成。",
  "Kód se skládá konfigurátorem. Viola.cz má např. VEGAPULS C 11 (PSC11GB).": "订货号由配置器生成。Viola.cz 有例如 VEGAPULS C 11（PSC11GB）。",
  "Kód se skládá konfigurátorem; neověřen.": "订货号由配置器生成；未核实。",
  "Kód výrobce ze zahraničního distributora. České zastoupení Xylem neověřeno; Lowara SV prodávají české e-shopy s čerpadly.": "制造商订货号来自国外经销商。Xylem 捷克代理未核实；捷克泵类网店销售 Lowara SV。",
  "Kód z e-shopu GEMÜ (titulek ve výsledku hledání; stránka při kontrole vracela 404). Význam pozic za DN (materiál těla, těsnění, funkce NC, velikost pohonu) ověřit v typovém klíči datasheetu 554; indikátor / koncové spínače se objednávají zvlášť. Česká pobočka neověřena.": "订货号来自 GEMÜ 网店（搜索结果中的标题；核查时页面返回 404）。DN 后各位的含义（阀体材料、密封、NC 功能、执行器规格）需在 554 数据表的型号代码中核实；指示器 / 限位开关需单独订购。捷克分公司未核实。",
