  "MAG 5100 W — přírubový senzor DN15–DN1200 (voda)": "MAG 5100 W — 法兰式传感器 DN15–DN1200（水）",
  "MAIN.st: GX Works3 edituje tělo programu odděleně od návěští — do ProgPou (ST) vlož jen tělo (od řádku za END_VAR po END_PROGRAM) a lokální návěští založ podle bloku VAR.": "MAIN.st：GX Works3 将程序体与标签分开编辑 — 在 ProgPou（ST）中只粘贴程序体（从 END_VAR 之后一行到 END_PROGRAM），并按 VAR 块创建局部标签。",
  "MAIN.st: Sysmac edituje tělo programu odděleně od proměnných — do Program0 (ST) vlož jen tělo (od řádku za END_VAR po END_PROGRAM) a proměnné z bloku VAR založ v tabulce lokálních proměnných.": "MAIN.st：Sysmac 将程序体与变量分开编辑 — 在 Program0（ST）中只粘贴程序体（从 END_VAR 之后一行到 END_PROGRAM），并在局部变量表中按 VAR 块创建变量。",
  "MAIN.st: obsah do MAIN (PRG) a zavolej v PlcTask.": "MAIN.st：内容放入 MAIN (PRG)，并在 PlcTask 中调用。",
  "MAIN: vytvoř POU „MAIN“ (Program, ST) a přidej ho do MainTask místo PLC_PRG.": "MAIN：创建 POU“MAIN”（Program，ST），并替代 PLC_PRG 加入 MainTask。",
