  "Napoj HMI na proměnné strojního bloku (TODO komentáře): modeAuto (přepínač AUTO / ruční),\n   cmdAutoStart (start cyklu), cmdAck (kvitace poruchy), manRun_* / manOpen_* (ruční povely\n   zařízení — platí při vypnutém AUTO). Stav poruchy: machineFault, krok s timeoutem: faultStep.\n   Chování: chyba kteréhokoli bloku nebo timeout kroku zastaví sekvenci a vypne její povely;\n   nový start je možný až po odstranění příčiny a kvitaci. Zkontroluj rozsahy analogů.": "将 HMI 连接到机器功能块的变量（TODO 注释）：modeAuto（AUTO / 手动切换开关）、\n   cmdAutoStart（循环启动）、cmdAck（故障确认）、manRun_* / manOpen_*（设备手动命令\n   — AUTO 关闭时有效）。故障状态：machineFault，发生超时的步：faultStep。\n   行为：任一功能块出错或步超时都会停止顺序控制并复位其命令；\n   只有排除原因并进行故障确认后才能重新启动。请检查模拟量量程。",
