  "Názvy řad převzaty z obecné znalosti, na webu v této rešerši neověřeny.": "系列名称来自一般知识，本次调研未在网站上核实。",
  "Názvy řad z obecné znalosti, neověřeny v této rešerši.": "系列名称来自一般知识，本次调研未核实。",
  "Nízkonapěťové motory Siemens převzala firma Innomotics (dceřiná Siemens AG); vyrábí se mj. v Mohelnici (Innomotics, s.r.o., odštěpný závod Elektromotory Mohelnice). Datový list: https://inverterdrive.com/file/Siemens-1LE1003-0DB32-2AA4-Datasheet": "Siemens 低压电机已由 Innomotics（Siemens AG 子公司）接管；生产地之一为 Mohelnice（Innomotics, s.r.o., odštěpný závod Elektromotory Mohelnice）。数据表：https://inverterdrive.com/file/Siemens-1LE1003-0DB32-2AA4-Datasheet",
  "Některá zařízení z návrhu program nečte nebo neovládá — stroj tak nedělá všechno, co popis slibuje. Seznam je v nálezech níže; doplň je do blokování, sekvence nebo vlastní logiky.": "设计中的部分设备未被程序读取或控制 — 因此机器无法完成描述中承诺的全部功能。清单见下方发现项；请将其补充到联锁、顺序控制或自定义逻辑中。",
  "Německý e-shop s automatizací (Siemens aj.); dodání do ČR neověřeno.": "德国自动化网店（Siemens 等）；向捷克供货未核实。",
