  "O1D100 — laserový snímač vzdálenosti 0,2–10 m (difuzní), analogový výstup 4–20 mA, M12": "O1D100 — 激光测距传感器 0.2–10 m（漫反射），模拟量输出 4–20 mA，M12",
  "O5H500 — difuzní snímač s potlačením pozadí 50–1800 mm, PNP, M12": "O5H500 — 带背景抑制的漫反射传感器 50–1800 mm，PNP，M12",
  "OD1000-6001R15 — laserový snímač vzdálenosti 200–1000 mm, analogový výstup přepínatelný 4–20 mA / 0–10 V, spínací výstup, 18–30 V DC": "OD1000-6001R15 — 激光测距传感器 200–1000 mm，模拟量输出可切换 4–20 mA / 0–10 V，开关量输出，18–30 V DC",
