  "Objednací kód": "订货号",
  "Objednací kód se skládá podle typového klíče v datasheetu HA 7111 (čerpadlo, tlak, motor, nádrž); konkrétní kód na stránce distributora neověřen. Primárně pro zvedací plošiny a přerušovaný provoz. Řada SMA05 (do 17 l/min, 250 bar): https://www.argo-hytos.com/fileadmin/user_upload/Datasheet_SMA05_ha7212_EN.pdf": "订货号按数据表 HA 7111 中的型号代码组合（泵、压力、电机、油箱）；经销商页面上的具体订货号未核实。主要用于升降平台和间歇运行。SMA05 系列（最高 17 l/min，250 bar）：https://www.argo-hytos.com/fileadmin/user_upload/Datasheet_SMA05_ha7212_EN.pdf",
  "Objednací číslo (MLFB 2KJ3…-Z, 17 míst + volby) se skládá v konfigurátoru Siemens; univerzální kód pro 0,75 kW neexistuje, proto neuveden.": "订货号（MLFB 2KJ3…-Z，17 位 + 选项）在 Siemens 配置器中生成；0.75 kW 没有通用订货号，因此未列出。",
  "Objednací číslo SICK 1040764 = typ IME12-04BPSZC0S. Viola.cz uvádí u téhož čísla NC – před objednáním ověřit funkci výstupu v datasheetu.": "SICK 订货号 1040764 = 型号 IME12-04BPSZC0S。Viola.cz 对同一编号标注为 NC – 订购前在数据表中核实输出功能。",
  "Objednací číslo SICK pravděpodobně 6038615 (jen z webu hydracentre.com) – ověřit.": "SICK 订货号可能为 6038615（仅来自 hydracentre.com）– 需核实。",
