  "Oficiální evropský e-shop; dodání do ČR neověřeno.": "官方欧洲网店；向捷克供货未核实。",
  "Oficiální stránky výrobců: produkt, vývojové prostředí, reference jazyka, manuály, import zdrojů a podpora. Odkazy byly ověřené k datu rešerše; výrobci je mohou přesunout. Klik otevře odkaz v prohlížeči.": "制造商官方页面：产品、开发环境、语言参考、手册、源文件导入和支持。链接已于调研日期核实；制造商可能会移动它们。点击在浏览器中打开链接。",
  "Oficiální stránky výrobců: produkt, vývojové prostředí, reference jazyka, příručky, postup importu a podpora. Odkazy byly ověřené k datu rešerše ({date}); výrobci je mohou měnit — když odkaz nefunguje, hledej název dokumentu na webu výrobce.": "制造商官方页面：产品、开发环境、语言参考、手册、导入步骤和支持。链接已于调研日期（{date}）核实；制造商可能会更改 — 如果链接失效，请在制造商网站上搜索文档名称。",
  "Oficiální zastoupení Schmersal v ČR: Bechyňská 640, 199 00 Praha 9 - Letňany, mercom@mercom.cz. Schmersal nemá vlastní českou pobočku.": "Schmersal 在捷克的官方代理：Bechyňská 640, 199 00 Praha 9 - Letňany，mercom@mercom.cz。Schmersal 在捷克没有自己的分公司。",
