  "PL6-C10/1 – jistič 1pól, 10 A, char. C, 6 kA": "PL6-C10/1 – 断路器 1 极，10 A，C 特性，6 kA",
  "PLC (programovatelný logický automat) je průmyslový počítač, který řídí stroj: čte vstupy (tlačítka, snímače), vyhodnotí program a nastaví výstupy (stykače, ventily, signálky). Na rozdíl od běžného PC je stavěný na nepřetržitý provoz, rušení a teploty v rozvaděči.": "PLC（可编程逻辑控制器）是控制机器的工业计算机：它读取输入（按钮、传感器），执行程序并设置输出（接触器、阀、指示灯）。与普通 PC 不同，它是为连续运行、抗干扰和电控柜内的温度环境而设计的。",
  "PLC Modicon M241": "PLC Modicon M241",
  "PLC Studio (návrh k revizi)": "PLC Studio（待审核草案）",
  "PLC Studio nejde spustit": "无法启动 PLC Studio",
  "PLC Studio: návrh k revizi, neověřeno importem ve Studiu 5000.": "PLC Studio：待审核草案，未经 Studio 5000 导入验证。",
  "PLC — {name}": "PLC — {name}",
  "PLC-RSC- 24DC/21 – reléový modul 6,2 mm (svorkovnice + zásuvné relé), 1 přepínací kontakt 6 A, 24 V DC, šroubové svorky": "PLC-RSC- 24DC/21 – 继电器模块 6.2 mm（端子底座 + 插拔式继电器），1 个转换触点 6 A，24 V DC，螺钉端子",
  "PLCStudio_Program.L5X (hlavní cesta): v Controller Organizer pravý klik na MainTask →\n  Add → Import Program… a vyber soubor. Vznikne program {prog} s rutinou MainRoutine (ST)\n  a programovými tagy, Add-On Instructions FB_Motor / FB_Ventil / FB_AnalogIn / FB_AnalogOut\n  a I/O tagy (controller scope). Pak Verify Controller. Soubor nese verzi {rev} — pro starší\n  verzi Logix Designeru uprav atribut SoftwareRevision.": "PLCStudio_Program.L5X（主要途径）：在 Controller Organizer 中右键单击 MainTask →\n  Add → Import Program… 并选择该文件。将生成程序 {prog}，含例程 MainRoutine (ST)\n  和程序标签、Add-On Instructions FB_Motor / FB_Ventil / FB_AnalogIn / FB_AnalogOut\n  以及 I/O 标签（controller scope）。然后执行 Verify Controller。文件版本为 {rev}——如使用较旧的\n  Logix Designer 版本，请修改 SoftwareRevision 属性。",
  "PLCopen – XML výměna (TC6, specifikace 2.01)": "PLCopen – XML 交换（TC6，规范 2.01）",
  "PNOZ X2.8P 24VACDC 3n/o 1n/c — E-stop / ochranné dveře, 1–2kanálově, 22,5 mm": "PNOZ X2.8P 24VACDC 3n/o 1n/c — 急停 / 防护门，1–2 通道，22.5 mm",
