  "POZOR — NEOVĚŘENO PŘEKLADEM: výstup pro Logix nebyl zkoušen ve Studiu 5000. Struktura L5X\nvychází z příručky 1756-RM014 a reálných exportů. Při prvním importu zkontroluj hlášení importu\na Verify Controller (hlavně FBD_TIMER v AOI, výchozí hodnoty parametrů a verzi souboru).": "注意——未经编译验证：Logix 输出尚未在 Studio 5000 中测试。L5X 结构\n依据手册 1756-RM014 和实际导出文件。首次导入时请检查导入信息\n和 Verify Controller（尤其是 AOI 中的 FBD_TIMER、参数默认值和文件版本）。",
  "POZOR — NEOVĚŘENO PŘEKLADEM: výstup pro Unitronics nebyl zkoušen v UniLogic. Při prvním\nvložení zkontroluj syntaxi proti své verzi (CASE, volání TON, převody TO_REAL / TO_INT).": "注意 — 未经编译验证：Unitronics 的输出未在 UniLogic 中测试过。首次\n粘贴时请对照所用版本检查语法（CASE、TON 调用、TO_REAL / TO_INT 转换）。",
