  "Panel CP-Link 4 potřebuje PC s vysílačem CP-Link 4 / DVI; zda jde přímo s CX7000, jsem neověřil – u malého CX může být vhodnější webový panel nebo panelové PC.": "CP-Link 4 面板需要带 CP-Link 4 / DVI 发送器的 PC；能否直接配合 CX7000 使用尚未核实 – 对小型 CX 而言，Web 面板或面板 PC 可能更合适。",
  "PanelView 5310 – 7\" širokoúhlý dotykový, 800×480, 24 V DC, Ethernet": "PanelView 5310 – 7\" 宽屏触摸屏，800×480，24 V DC，Ethernet",
  "Parametry {dev} uloženy.": "{dev} 的参数已保存。",
  "Pasivní dělič napětí: napájením 10 V dá 0–10 V (nutný vstup s vysokou impedancí); pro 4–20 mA přidat převodník signálu. Česká distribuce Novotechnik neověřena.": "无源分压器：10 V 供电时输出 0–10 V（需高阻抗输入）；如需 4–20 mA 应加信号转换器。Novotechnik 在捷克的分销未核实。",
