  "Platforma řízení:": "控制平台：",
  "Platforma řízení: **{plat}**. Značky a typy jsou typické volby z katalogu PLC Studia — podklad k poptávce, ne projekt elektro. Dimenzování a bezpečnostní prvky podle posouzení rizik ověří projektant (návrh k revizi).": "控制平台：**{plat}**。品牌和型号是 PLC Studio 目录中的典型选择 — 用作询价依据，不是电气设计。规格选型和安全元件由设计人员根据风险评估核实（设计待审核）。",
