  "Podpora": "支持",
  "Pohon LR24A se objednává zvlášť (https://www.belimo.cz/lr24a/). Belimo míří hlavně na TZB/HVAC — pro procesní média ověřit vhodnost; pomocné spínače polohy u LR24A nejsou uvedeny.": "执行器 LR24A 需单独订购（https://www.belimo.cz/lr24a/）。Belimo 主要面向楼宇设备/HVAC — 用于工艺介质时需核实适用性；LR24A 未列出辅助位置开关。",
  "Pohony (motory, čerpadla)": "驱动（电机、泵）",
  "Pokračovat": "继续",
  "Poloha lisu (lineární snímač)": "压机位置（直线位移传感器）",
  "Poloha se snímá bezkontaktně přes posuvný magnet (objednává se zvlášť). Profilové provedení např. BTL7-E501-M0300-P-S32 (výstup 4–20 / 20–4 mA).": "通过滑动磁铁非接触检测位置（磁铁单独订购）。型材式型号例如 BTL7-E501-M0300-P-S32（输出 4–20 / 20–4 mA）。",
