  "Posouzení rizik a validace bezpečnostních funkcí (ISO 13849 / IEC 62061)": "风险评估和安全功能确认 (ISO 13849 / IEC 62061)",
  "Postup importu pro danou platformu je v souboru README.txt. Výstup je výchozí kostra — TODO komentáře označují místa k doplnění. Generovaný kód je návrh k revizi; bezpečnostní funkce řeší certifikovaná safety technika.": "所选平台的导入步骤见 README.txt 文件。输出是初始框架 — TODO 注释标出了待补充之处。生成的代码是待审核草案；安全功能由经认证的安全技术实现。",
  "Postup importu pro danou platformu je v záložce <b>README.txt</b>. Výstup je výchozí kostra — TODO komentáře označují místa k doplnění.": "所选平台的导入步骤见 <b>README.txt</b> 选项卡。输出是初始框架 — TODO 注释标出了待补充之处。",
  "Potřebuji upřesnit:": "需要补充说明：",
  "PowerXL DE1 (frekvenční spouštěč)": "PowerXL DE1（变频起动器）",
  "Pozice": "位号",
  "Poznámka": "备注",
  "Poznámka:": "备注：",
  "Pozor: M2BAX 80MB4 (3GBA082320-…) je provedení IE2, pro EU použít IE3 variantu 80MLA4.": "注意：M2BAX 80MB4（3GBA082320-…）为 IE2 型号，欧盟应使用 IE3 型号 80MLA4。",
  "Pozor: NC/NO kontakty dle sloupce NC v kroku I/O; čísla vodičů -W1xx dle potenciálových řad. Jištění, průřezy, relé na výstupech s větší zátěží a stínění analogů doplní projektant elektro — toto je podklad, ne výrobní dokumentace. DXF otevře EPLAN / AutoCAD / LibreCAD.": "注意：NC/NO 触点依据“I/O”步骤中的 NC 列；导线编号 -W1xx 按电位组编排。保护、导线截面、大负载输出的继电器以及模拟量屏蔽由电气设计人员补充 — 这只是设计依据，不是生产用文档。DXF 可用 EPLAN / AutoCAD / LibreCAD 打开。",
  "Pozor: tranzistorové výstupy jsou NPN, ostatní reléové.": "注意：晶体管输出为 NPN，其余为继电器输出。",
  "Počet portů a krytí na stránce nebyly – ověřit.": "页面上没有端口数量和防护等级 – 需核实。",
