  "Program závadu nezachytí, sekvence zůstane stát v kroku {n}.": "程序未检测到该异常，顺序控制停在第 {n} 步。",
  "Program závadu nezachytí, sekvence zůstane stát v kroku {n}; sepnuté zůstávají: {tags}.": "程序未检测到该异常，顺序控制停在第 {n} 步；仍保持接通：{tags}。",
  "Program závadu nezachytí.": "程序未检测到该异常。",
  "Program závadu nezachytí; sepnuté zůstávají: {tags}.": "程序未检测到该异常；仍保持接通：{tags}。",
  "Program čeká TRUE = v pořádku (rozpínací kontakt). U spínacího kontaktu by přerušený vodič stroj nezastavil — označ vstup jako NC v kroku I/O.": "程序按 TRUE = 正常（常闭触点）处理。若使用常开触点，导线断开时机器不会停止 — 请在“I/O”步骤中将该输入标记为 NC。",
  "Program čeká TRUE = v pořádku. U spínacího kontaktu by přerušený vodič vypadal jako zavřený kryt / volná závora — použij NC a označ vstup v kroku I/O.": "程序期望 TRUE = 正常。若使用常开触点，导线断开时看起来就像防护罩已关闭 / 光幕无遮挡 — 请使用 NC，并在 I/O 步骤中标记该输入。",
  "Program – časovač": "程序 – 定时器",
  "Programovací příručka S7-1200/S7-1500 (SCL, optimální programování, PDF)": "S7-1200/S7-1500 编程手册（SCL，优化编程，PDF）",
  "Programové tagy patří do programu {prog}; instance FB_* vyžadují AOI z PLCStudio_Program.L5X.": "程序标签属于程序 {prog}；FB_* 实例需要来自 PLCStudio_Program.L5X 的 AOI。",
  "Projdi kroky zleva doprava — návrh se průběžně ukládá a mezi kroky se můžeš kdykoli vracet a vstupy upřesňovat; výstupy se vždy přepočítají. Nejrychlejší start: popiš stroj v kroku AI návrh. Existující projekt převezmeš volbou Import v kroku Zařízení. Pokud s PLC začínáš, otevři Nápovědu (tlačítko vpravo v liště kroků). Soubor projektu (.plcstudio.json) je zaměnitelný s exportem z webové verze PLC Studia.": "按从左到右的顺序完成各步骤 — 设计会持续自动保存，你可以随时在步骤之间返回并细化输入；输出总会重新计算。最快的开始方式：在“AI 设计”步骤中描述机器。现有项目可通过“设备”步骤中的“导入”选项接入。如果你刚接触 PLC，请打开“帮助”（步骤栏右侧的按钮）。项目文件 (.plcstudio.json) 可与 PLC Studio 网页版的导出文件互换使用。",
  "Projdi kroky zleva doprava — návrh se průběžně ukládá v prohlížeči a mezi kroky se můžeš kdykoli vracet a vstupy upřesňovat; výstupy se vždy přepočítají. Nejrychlejší start: popiš stroj v kroku <b>AI návrh</b>. Existující projekt převezmeš vedlejší volbou <b>Import</b> dole v kroku Zařízení. Pokud s PLC začínáš, otevři <b>Nápovědu</b> (tlačítko vpravo v liště kroků).": "按从左到右的顺序完成各步骤 — 设计会持续自动保存在浏览器中，你可以随时在步骤之间返回并细化输入；输出总会重新计算。最快的开始方式：在 <b>AI 设计</b> 步骤中描述机器。现有项目可通过“设备”步骤下方的辅助选项 <b>导入</b> 接入。如果你刚接触 PLC，请打开 <b>帮助</b>（步骤栏右侧的按钮）。",
