  "Sekvence čeká na režim AUTO a povel start. Při ztrátě enable (E-stop) se sem vrací a bloky vypnou výstupy.": "顺序控制等待 AUTO 模式和启动命令。enable (E-stop) 丢失时返回此处，功能块关断输出。",
  "Sekvence čeká na režim AUTO, uvolnění, stav bez poruchy a povel start (cmdAutoStart).": "顺序控制等待 AUTO 模式、使能、无故障状态和启动命令 (cmdAutoStart)。",
