  "Siemens-Innomotics motory skladem, dodání do 24 h.": "Siemens-Innomotics 电机有现货，24 小时内发货。",
  "Signal horn WM 24VAC/DC GY — elektronická houkačka, trvalý tón, 98 dB(A)/1 m, nastavitelná hlasitost, IP65, nástěnná": "Signal horn WM 24VAC/DC GY — 电子喇叭，持续音，98 dB(A)/1 m，音量可调，IP65，壁挂式",
  "Signalizace a zámky (vazba na stav stroje)": "信号与锁（与机器状态关联）",
  "Signál enable je trvale TRUE — program stroj na žádný vstup nezastaví. Zvol vstup v kroku Program.": "enable 信号恒为 TRUE — 程序不会因任何输入而停止机器。请在“程序”步骤中选择输入。",
  "Signál je jen mezi volnými signály — na jeho stav stroj nereaguje. Pokud jde o kryt, závoru nebo jiné uvolnění, zařaď ho do blokovacích vstupů; jinak (tlačítko, podmínka kroku, hlídání zásobníku) doplň logiku ručně.": "该信号仅属于空闲信号 — 机器不响应其状态。如果是防护罩、光幕或其他使能信号，请将其加入联锁输入；否则（按钮、步条件、料仓监控）请手动补充逻辑。",
  "Signál se zapojí do <code>enable</code> všech bloků. Skutečnou bezpečnost řeší safety technika, ne program — viz Nápověda.": "该信号将接入所有功能块的 <code>enable</code>。真正的安全由安全技术保证，而不是由程序保证 — 参见“帮助”。",
  "Signál se zapojí do enable všech bloků. Skutečnou bezpečnost řeší safety technika (bezpečnostní relé / safety PLC dle posouzení rizik), ne program — E-stop je v programu jen informativní signál. Viz Nápověda.": "该信号将接入所有功能块的 enable。真正的安全由安全技术（根据风险评估采用安全继电器 / 安全 PLC）保证，而不是由程序保证 — E-stop 在程序中仅为信息信号。参见“帮助”。",
  "Signálka": "指示灯",
  "Signálka Připraveno": "就绪指示灯",
  "Signální maják": "信号灯",
  "Siloměr / tenzometr": "测力计 / 应变传感器",
  "Silový kabel": "动力电缆",
  "Simulace": "仿真",
  "Simulace a ověření ↗": "仿真与验证 ↗",
  "Simulace externí poruchy → porucha": "模拟外部故障 → 故障",
  "Simulace nedojetí → timeout, porucha": "模拟未到位 → 超时，故障",
  "Simulace ověřuje návrh proti modelu generovaných bloků (stavové automaty a timeouty shodné s Gen_Library) a zjednodušenému modelu stroje. Neověřuje kód přeložený v cílovém IDE, HW konfiguraci ani bezpečnostní funkce — nenahrazuje test v simulátoru platformy a FAT.": "仿真将设计与所生成功能块的模型（状态机和超时与 Gen_Library 一致）以及简化的机器模型进行对照验证。它不验证在目标 IDE 中编译的代码、硬件组态和安全功能 — 不能替代平台仿真器中的测试和 FAT。",
  "Simulace ověřuje návrh, ne kód přeložený v cílovém IDE, HW konfiguraci ani bezpečnostní funkce. Nenahrazuje test v simulátoru platformy a FAT.": "仿真验证的是设计，而不是在目标 IDE 中编译的代码、硬件组态或安全功能。它不能替代平台仿真器中的测试和 FAT。",
  "Simulace poruchy bloku / nedojetí v kroku → porucha stroje, sekvence do kroku 0, povely vypnuty": "模拟某步中功能块故障 / 未到位 → 机器故障，顺序控制回到第 0 步，命令复位",
  "Simulace ztráty hlášení za chodu → porucha, výstup vypnut": "模拟运行中反馈丢失 → 故障，输出关断",
  "Simulátor provádí scan po scanu logiku generovaných bloků (stavové automaty FB_Motor a FB_Ventil, timeouty {motor} s a {valve} s, sekvence CASE s hlídáním času kroků, porucha stroje a kvitace) proti modelu stroje.": "仿真器逐个扫描周期执行所生成功能块的逻辑（FB_Motor 和 FB_Ventil 的状态机、{motor} s 和 {valve} s 的超时、带步时间监控的 CASE 顺序控制、机器故障和故障确认），并与机器模型交互运行。",
