  "Symbolické adresování, bez M-flagů; tagy `<Zařízení>_<signál>`; hrany uvnitř FB; každý čekací stav má timeout do ERROR. Dle Siemens Programming Styleguide (ID 81318674) / IEC 61131-3.": "符号寻址，不使用 M 标志位; 变量 `<设备>_<信号>`; 边沿检测在 FB 内部; 每个等待状态都有转入 ERROR 的超时。依据 Siemens Programming Styleguide (ID 81318674) / IEC 61131-3。",
