  "TME nabízí řadu variant 3SE5112-0…; konkrétní typ podle hlavice z konfigurátoru Siemens (popis variant tu nebyl ověřen).": "TME 提供多种 3SE5112-0… 型号；具体型号按 Siemens 配置器中的操作头确定（此处未核实各型号描述）。",
  "TON na FX5 bere nejvýš 32767 ms — kroky s delším časem kontrola návrhu hlásí; uprav je (např. TIMER_100_FB_M nebo rozdělení kroku).": "FX5 上的 TON 最大 32767 ms — 设计检查会提示时间更长的步骤；请调整（例如 TIMER_100_FB_M 或拆分步骤）。",
