  "Tag": "变量",
  "Tag je delší než 40 znaků — Rockwell Logix ho nepřijme.": "标签超过 40 个字符——Rockwell Logix 不接受。",
  "Tag koliduje s klíčovým slovem IEC 61131-3.": "变量名与 IEC 61131-3 关键字冲突。",
  "Tag není platný identifikátor IEC 61131-3 (písmena bez diakritiky, číslice, jedno _) — žádná platforma ho nepřijme. Doporučeno: {tag}": "该变量不是有效的 IEC 61131-3 标识符（不带变音符号的字母、数字、单个 _）— 任何平台都不会接受。建议：{tag}",
  "Tag obsahuje diakritiku/mezery — Rockwell, GX Works3 a Sysmac ho odmítnou. Doporučeno: {tag}": "变量名含非 ASCII 字符/空格 — Rockwell、GX Works3 和 Sysmac 会拒绝。建议：{tag}",
  "Tag;Adresa;Směr;Datový typ;Zařízení;Komentář": "变量;地址;方向;数据类型;设备;注释",
  "Tags.csv (náhradní cesta): Tools → Import → Tags and Logic Comments. I/O jsou v něm ALIAS\n  na Local:<slot>:I.Pt<nn>.Data (DI/DO) a Ch<nn>.Data (AI/AO) podle předpokládaného osazení\n  lokálních slotů: {slots}. Moduly musí v I/O Configuration existovat dřív než import; když se\n  osazení liší, uprav sloupec SPECIFIER. Programové tagy mají SCOPE {prog}, instance bloků\n  (FB_*) projdou jen tehdy, když jsou AOI už v projektu (z L5X). Soubor needituj v Excelu.": "Tags.csv（备用途径）：Tools → Import → Tags and Logic Comments。其中 I/O 为 ALIAS，\n  指向 Local:<slot>:I.Pt<nn>.Data (DI/DO) 和 Ch<nn>.Data (AI/AO)，依据假定的本地\n  槽位配置：{slots}。导入前模块必须已存在于 I/O Configuration 中；如果\n  配置不同，请修改 SPECIFIER 列。程序标签的 SCOPE 为 {prog}；功能块实例\n  (FB_*) 仅在项目中已有 AOI（来自 L5X）时才能导入。请勿在 Excel 中编辑该文件。",
  "Tags.csv: seznam tagů k založení jako GLOBÁLNÍ (skupiny I/O = fyzické signály,\n  {prog} a {block} = stav logiky, {timer} = instance TON). UniLogic importuje jen\n  soubor, který sám exportoval: buď tagy založ ručně, nebo vyexportuj prázdnou šablonu\n  (PLC → Import/Export), doplň ji podle Tags.csv a naimportuj zpět. I/O tagy pak přiřaď\n  vstupům a výstupům v konfiguraci hardwaru (sloupec „I/O address hint\" je jen vodítko).": "Tags.csv：需创建为全局变量的变量清单（I/O 组 = 物理信号，\n  {prog} 和 {block} = 逻辑状态，{timer} = TON 实例）。UniLogic 只能导入\n  由它自己导出的文件：可手动创建变量，或先导出空模板\n  （PLC → Import/Export），按 Tags.csv 补全后再导入。然后在硬件组态中将 I/O 变量\n  分配给输入和输出（I/O address hint 列仅供参考）。",
