  "Uni-I/O se nasazuje na záda panelu nebo na DIN lištu přes Local Expansion Adapter.": "Uni-I/O 安装在面板背面，或通过 Local Expansion Adapter 安装在 DIN 导轨上。",
  "UniLogic programuje UniStream v Ladderu, C a Structured Textu. ST se píše jako FUNKCE,\n  která nemá vlastní paměť (lokální tagy mezi voláními hodnotu nedrží). Logika bloků je\n  proto rozepsaná „naplocho\" do jedné funkce a veškerý stav je v globálních tazích\n  s předponou instance (instM1_statStep, instY1_tonOpen…). Knihovna Gen_Library se\n  u této platformy negeneruje.": "UniLogic 使用 Ladder、C 和 Structured Text 对 UniStream 编程。ST 以函数形式编写，\n  函数没有自己的存储区（局部变量在两次调用之间不保持数值）。因此功能块逻辑\n  被展开写入同一个函数，全部状态保存在带实例前缀的全局变量中\n  （instM1_statStep、instY1_tonOpen…）。该平台\n  不生成 Gen_Library 库。",
  "UniLogic – stránka softwaru a stažení zdarma": "UniLogic – 软件页面及免费下载",
  "UniStream US5 / US7 / US10 (HMI vestavěno)": "UniStream US5 / US7 / US10（内置 HMI）",
  "UniStream – produktová stránka": "UniStream – 产品页面",
  "Unitronics Help Center – podpora a tikety": "Unitronics Help Center – 技术支持与工单",
  "Univerzální pro válce různých výrobců s T-drážkou.": "通用于各厂商带 T 型槽的气缸。",
  "Upozornění nejsou chyby generátoru, ale místa, kde návrh spoléhá na doplnění ručně nebo na rozhodnutí projektanta.": "警告并非生成器的错误，而是设计中依赖手动补充或设计人员决策之处。",
  "Upravit v programu": "在程序中编辑",
  "Upínací válec levý": "左夹紧缸",
  "Upínací válec pravý": "右夹紧缸",
  "Uveden typ, ne šestimístné číslo Eaton (276690 je verze 230 V AC — nezaměnit). Levnější řada DILM…-EA viz TME.": "列出的是型号，不是 Eaton 六位编号（276690 是 230 V AC 型号 — 勿混淆）。更便宜的 DILM…-EA 系列见 TME。",
  "Uveden typ, šestimístné číslo Eaton neověřeno.": "列出的是型号，Eaton 六位编号未核实。",
  "Uvolnit vše": "全部释放",
  "V Chotejně 700/7, Praha 10.": "V Chotejně 700/7, Praha 10。",
  "V klidu a v každém kroku byl vyzkoušen každý zásah ({cols}); stroj vždy zastavil, poruchy byly vyhlášeny a nový start byl zablokovaný.": "在空闲和每一步中均测试了每种干预（{cols}）；机器每次都停止，故障均已报出，重新启动均被闭锁。",
  "V klidu a v každém kroku se vyzkouší každý zásah. ✔ = reakce odpovídá konceptu (stroj zastaven, porucha vyhlášena, nový start zablokovaný), ✖ = neodpovídá, — = kombinace nedává smysl. Dvojklik na buňku přehraje kombinaci.": "在空闲和每一步中测试每种干预。✔ = 响应符合设计概念（机器停止、报出故障、重新启动被闭锁），✖ = 不符合，— = 该组合无意义。双击单元格可回放该组合。",
  "V klidu a v každém kroku se vyzkouší každý zásah. ✔ = reakce odpovídá konceptu (stroj zastaven, porucha vyhlášena, nový start zablokovaný), ✖ = neodpovídá, — = kombinace nedává smysl. U poruch je uvedena doba do vyhlášení poruchy.": "在空闲和每一步中测试每种干预。✔ = 响应符合设计概念（机器停止、报出故障、重新启动被闭锁），✖ = 不符合，— = 该组合无意义。对于故障，显示到报出故障为止的时间。",
  "V krabici: M22-PV/KC11/IY = 216525. Volba a zapojení podle posouzení rizik (EN ISO 13849), návrh k revizi.": "带盒装：M22-PV/KC11/IY = 216525。按风险评估（EN ISO 13849）选型和接线，设计待审核。",
  "V kusovníku 0 ks navíc.": "物料清单中无额外件数。",
  "V programu": "在程序中",
  "V režimu AUTO spustit cyklus tlačítkem start.": "在 AUTO 模式下按启动按钮开始循环。",
  "V režimu AUTO stojí; ovládá se jen ručním povelem. Pokud má v cyklu pracovat, doplň krok sekvence.": "在 AUTO 模式下静止；仅可通过手动命令控制。如需在循环中工作，请补充一个顺序控制步。",
