  "Vestec u Prahy (Vídeňská 185) a Zlín; oficiální distributor Unitronics pro ČR (dle unitronicsplc.com), +420 244 001 558. Zastupuje přes 20 výrobců: senzorika a automatizace (Leuze — autorizovaný distributor, Pizzato, PLC), pohony (elektromotory, měniče, serva), strojírenství (čerpadla, spojky); výhradní distributor Wieland pro ČR.": "Vestec u Prahy（Vídeňská 185）和 Zlín；Unitronics 在捷克的官方分销商（据 unitronicsplc.com），+420 244 001 558。代理 20 多家制造商：传感器与自动化（Leuze — 授权分销商，Pizzato，PLC）、驱动（电动机、变频器、伺服）、机械（泵、联轴器）；Wieland 在捷克的独家分销商。",
