  "Vhodné pro vzdálenost / polohu na delší dráze (zásobník, pojezd). Stránka výrobce: https://www.ifm.com/us/en/product/O1D100": "适用于较长行程上的距离 / 位置检测（料仓、行走机构）。制造商页面：https://www.ifm.com/us/en/product/O1D100",
  "Vibrační podavač dílů": "零件振动送料器",
  "Viděny Eaton PKZM0 (s objednacím číslem výrobce), Schneider GV2ME06, ATV320.": "可见 Eaton PKZM0（带制造商订货号）、Schneider GV2ME06、ATV320。",
  "Vision / Samba (VisiLogic) Structured Text nemá — tam Machine.st slouží jako předloha\n  pro přepis do Ladderu a Tags.csv jako seznam operandů.": "Vision / Samba (VisiLogic) 不支持 Structured Text — 此时 Machine.st 用作\n  改写为 Ladder 的蓝本，Tags.csv 用作操作数清单。",
  "Vlož dříve exportovaný JSON návrhu…": "粘贴之前导出的设计 JSON…",
  "Vlož export z existujícího projektu a PLC Studio z něj zpětně sestaví zařízení a I/O — klidně pro migraci na jinou platformu. Formáty se poznají automaticky: SimaticML XML, Rockwell L5X/CSV, GVL/ST, tabulky labelů (CSV/tab), prostý I/O list  Tag;Adresa;Zařízení;Třída;Komentář.": "粘贴现有项目的导出内容，PLC Studio 将据此反向重建设备和 I/O — 也可用于迁移到其他平台。格式自动识别：SimaticML XML、Rockwell L5X/CSV、GVL/ST、标签表 (CSV/tab)、简单 I/O 表  变量;地址;设备;类别;注释。",
  "Vlož export z existujícího projektu a PLC Studio z něj zpětně sestaví zařízení a I/O — klidně pro migraci na jinou platformu. Formáty se poznají automaticky: SimaticML XML, Rockwell L5X/CSV, GVL/ST, tabulky labelů (CSV/tab), prostý I/O list <code>Tag;Adresa;Zařízení;Třída;Komentář</code>.": "粘贴现有项目的导出内容，PLC Studio 将据此反向重建设备和 I/O — 也可用于迁移到其他平台。格式自动识别：SimaticML XML、Rockwell L5X/CSV、GVL/ST、标签表 (CSV/tab)、简单 I/O 表 <code>变量;地址;设备;类别;注释</code>。",
  "Vlož knihovnu šablon (Gen_Library), poté hlavní program (MAIN).": "先插入模板库 (Gen_Library)，再插入主程序 (MAIN)。",
  "Vlož logiku stroje (Machine.st) do ST funkce — knihovna šablon se u této platformy negeneruje.": "将机器逻辑 (Machine.st) 粘贴到 ST 函数中 — 该平台不生成模板库。",
  "Vložit do OB1 (Main)": "插入到 OB1 (Main)",
  "Vložit příklad": "插入示例",
  "Volba a zapojení podle posouzení rizik (EN ISO 13849) — návrh k revizi.": "按风险评估（EN ISO 13849）选型和接线 — 设计待审核。",
  "Volba a zapojení podle posouzení rizik (EN ISO 13849), návrh k revizi.": "按风险评估（EN ISO 13849）选型和接线，设计待审核。",
  "Volba a zapojení podle posouzení rizik (EN ISO 13849), návrh k revizi. Objednává se pár vysílač + přijímač (+ držáky); objednací čísla SICK 1211450 / 1211463 jen z distributora wiautomation – ověřit.": "按风险评估（EN ISO 13849）选型和接线，设计待审核。成对订购发射器 + 接收器（+ 支架）；SICK 订货号 1211450 / 1211463 仅来自经销商 wiautomation – 需核实。",
  "Volba výrobce platí pro všechny řádky této kategorie (i pro nové).": "制造商选择适用于该类别的所有行（包括新行）。",
  "Volbu nouzového vypínače dělat podle posouzení rizik (EN ISO 13849, EN 60204-1), návrh k revizi.": "急停开关按风险评估（EN ISO 13849，EN 60204-1）选型，设计待审核。",
