  "Werma píše číslo i s tečkami (649.240.05). Modulární věž se skládá z patice a modulů (kódy podle konfigurátoru Werma).": "Werma 的编号带点（649.240.05）。模块化信号塔由底座和模块组成（订货号按 Werma 配置器）。",
  "Wilo CS, s.r.o., Čestlice (tel. 234 098 711)": "Wilo CS, s.r.o., Čestlice（电话 234 098 711）",
  "XB5AA31 — zelené lícující tlačítko Ø22 s návratem, 1 Z (NO); červené 1 V: XB5AA42": "XB5AA31 — 绿色平头按钮 Ø22，自复位，1 NO；红色 1 NC：XB5AA42",
  "XB5AS8442 — hřib 40 mm červený, aretace, uvolnění pootočením, 1 V (NC)": "XB5AS8442 — 蘑菇头 40 mm 红色，自锁，旋转释放，1 NC",
  "XB5AVB3 — signálka Ø22 zelená, integrovaná LED 24 V; červená XB5AVB4": "XB5AVB3 — 指示灯 Ø22 绿色，集成 LED 24 V；红色 XB5AVB4",
  "XCKN2118P20 — plastové tělo, kladková páčka, 1NC+1NO, skoková, vývodka M20": "XCKN2118P20 — 塑料外壳，滚轮杠杆，1NC+1NO，速动，电缆接头 M20",
  "Z návrhu se generuje dokumentace běžného automatizačního projektu: FDS, I/O list, svorkovnice, seznam alarmů, FAT protokol, návod k obsluze, SW dokumentace, schémata (SVG + DXF) a zdrojové kódy platforem. Vyber soubor vlevo, prohlédni a ulož, kam potřebuješ.": "根据设计生成常规自动化项目的文档：FDS、I/O 表、端子排、报警列表、FAT 测试记录、操作手册、软件文档、原理图 (SVG + DXF) 以及各平台的源代码。在左侧选择文件，查看后保存到所需位置。",
  "Z návrhu vznikne kusovník: PLC a I/O moduly zvolené platformy, ke každému zařízení jeho komponenty (motor → jistič motoru a stykač, válec → rozváděč a snímače polohy…) a rozvaděč. Značky, typy a dodavatele nabízí katalog PLC Studia (stav k {date}); u řádku nebo celé kategorie je můžeš změnit nebo zadat vlastní.": "根据设计生成物料清单：所选平台的 PLC 和 I/O 模块，每台设备对应的元件（电机 → 电机保护断路器和接触器，气缸 → 换向阀和位置传感器…）以及电控柜。品牌、型号和供应商由 PLC Studio 目录提供（截至 {date}）；可按行或按整个类别修改，或输入自定义值。",
  "Z6 / PW6D (vážení)": "Z6 / PW6D（称重）",
  "Zadej požadovanou dobu cyklu v kroku Projekt — ověření ji pak porovná se simulací. Nejdelší kroky: {slow}.": "请在“项目”步骤中输入要求的循环时间 — 验证会将其与仿真结果比较。最长的步：{slow}。",
  "Zahodit aktuální návrh a začít s prázdným projektem?": "放弃当前设计并从空白项目开始？",
