  "Zatím žádná zařízení — přidej je výše, načti ukázku v kroku Projekt, nech si je navrhnout v kroku AI návrh, nebo použij Import níže.": "还没有设备 — 请在上方添加，在“项目”步骤中加载示例，在“AI 设计”步骤中让 AI 设计，或使用下方的“导入”。",
  "Zatím žádná zařízení — přidej je výše, načti ukázku v kroku Projekt, nech si je navrhnout v kroku AI návrh, nebo použij Import vpravo dole.": "还没有设备 — 请在上方添加，在“项目”步骤中加载示例，在“AI 设计”步骤中让 AI 设计，或使用右下方的“导入”。",
