  "Zaškrtni ☐→☑. Neshody zapiš do tabulky na konci. SAT = stejný rozsah po instalaci u zákazníka + skutečné akční členy a technologie.": "请勾选 ☐→☑。不符合项记入末尾的表格。SAT = 在客户现场安装后进行相同范围的测试 + 实际执行器和工艺。",
  "Zaškrtnuté vstupy jsou spolu s E-stopem v <code>enable</code>: FALSE kteréhokoli zastaví stroj (výstupy vypnout, sekvence do klidu, po obnovení nový start). Vstup má mít TRUE = v pořádku (kryt zavřen, závora volná).": "勾选的输入与急停一起构成 <code>enable</code>：任一为 FALSE 即停机（关闭输出，顺序控制回到空闲，恢复后重新启动）。输入应为 TRUE = 正常（防护门关闭，光幕畅通）。",
  "Zaškrtnuté vstupy jsou spolu s E-stopem v enable: FALSE kteréhokoli zastaví stroj (výstupy vypnout, sekvence do klidu, po obnovení nový start). Vstup má mít TRUE = v pořádku (kryt zavřen, závora volná).": "勾选的输入与急停一起构成 enable：任一为 FALSE 即停机（关闭输出，顺序控制回到空闲，恢复后重新启动）。输入应为 TRUE = 正常（防护门关闭，光幕畅通）。",
