  "Zdroje signálů → moduly PLC → akční členy. Klik na zařízení = popis a odkazy vpravo, klik na modul = jeho list zapojení.": "信号源 → PLC 模块 → 执行器。点击设备 = 右侧显示描述和链接，点击模块 = 其接线图页。",
