  "Číslo 178684 = Type 2000 G1/2 NC podle titulku Tameson (ve výsledku hledání „Brass“, v URL „stainless steel“ — materiál těla ověřit; stránka při kontrole vracela 404). Řada: https://www.burkert.com/en/type/2000. Řídicí hlava 8691: https://www.burkert.com/en/type/8691.": "编号 178684 = Type 2000 G1/2 NC，依据 Tameson 标题（搜索结果中为“Brass”，URL 中为“stainless steel” — 需核实阀体材料；核查时页面返回 404）。系列：https://www.burkert.com/en/type/2000。控制头 8691：https://www.burkert.com/en/type/8691。",
